import os,pathlib,stat,json
root=pathlib.Path('/home/appontrack/public_html/saas/console')
assert os.getuid()==2379 and root.is_dir() and not root.is_symlink()
count=0
for base,dirs,files in os.walk(root,followlinks=False):
 current=pathlib.Path(base)
 assert current==root or root in current.parents
 if current.is_symlink():raise RuntimeError('symlink dir')
 current.chmod(0o755)
 count+=1
 for name in dirs:
  if (current/name).is_symlink():raise RuntimeError('symlink child')
print(json.dumps({'status':'public_directories_traversable','directories':count,'root_mode':oct(stat.S_IMODE(root.stat().st_mode))}))
